#!/usr/bin/env node
/**
 * Read-only follow-up query over the JSON emitted by
 * tools/grammar-static-complexity.mjs.  Prints:
 *   - the Less statement-routing cluster in counts
 *   - dead (emitted-but-never-called) generated bytes per dialect
 *   - the cross-dialect "structurally worst rules" ranking
 *
 *   node tools/grammar-static-cluster.mjs <report.json>
 */
import { readFileSync } from 'node:fs';

const report = JSON.parse(readFileSync(process.argv[2], 'utf8'));
const primary = d => report.find(a => a.dialect === d).instances[0];

const CLUSTER = [
  '_92cdddb2__pf53', '_92cdddb2__pf266', '_92cdddb2__pf232',
  '_r_ClassIdStatement', '_r_ClassIdSelectorPrefix', '_92cdddb2__pf189',
  '_r_BodyStatement', '_r_Stylesheet', '_92cdddb2__pf52', '_92cdddb2__pf196',
  '_r_RulesetWithExtends', '_r_NestedRulesetWithExtends', '_r_SelectorBranchTail'
];

console.log('=== LESS STATEMENT-ROUTING CLUSTER (lessGrammar, primary instance) ===');
console.log('fn                                  line    bytes  choices arms gated ungated(call/inline) snap(att/not) depth');
let tot = { bytes: 0, arms: 0, ungated: 0, call: 0, snap: 0 };
for (const n of CLUSTER) {
  const f = primary('less').fns.find(x => x.name === n);
  if (!f) { console.log(`${n}  <not found>`); continue; }
  tot.bytes += f.bytes; tot.arms += f.totalArms; tot.ungated += f.ungatedArms;
  tot.call += f.ungatedCallFirst; tot.snap += f.snapshotCount;
  console.log(
    `${f.name.padEnd(34)} ${String(f.startLine).padStart(6)} ${String(f.bytes).padStart(8)} ` +
    `${String(f.choiceCount).padStart(6)} ${String(f.totalArms).padStart(5)} ${String(f.gatedArms).padStart(5)} ` +
    `${String(f.ungatedArms).padStart(6)}(${f.ungatedCallFirst}/${f.ungatedInlineTest})`.padEnd(20) +
    ` ${String(f.snapshotCount).padStart(4)}(${f.attemptSnapshots}/${f.notSnapshots})` +
    ` ${String(f.maxDepth).padStart(5)}`
  );
  for (const c of f.choices.filter(c => c.arms >= 3)) {
    console.log(`      choice ${c.id}: ${c.arms} arms, ${c.gatedArms} gated across ${c.distinctGuards} distinct guards, biggest guard group = ${c.largestGuardGroup}` +
      (c.guards[0] ? `  ("${c.guards[0][0].slice(0, 50)}")` : ''));
  }
}
console.log(`TOTAL bytes=${tot.bytes} arms=${tot.arms} ungated=${tot.ungated} (call-first=${tot.call}) snapshots=${tot.snap}`);

console.log('\n=== DEAD GENERATED CODE (named rule emitted but never called) ===');
for (const a of report) {
  const inst = a.instances[0];
  const dead = inst.fns.filter(f => inst.unreferenced.includes(f.name) && f.name.startsWith('_r_'));
  const bytes = dead.reduce((x, f) => x + f.bytes, 0);
  console.log(`${a.dialect.padEnd(5)} ${String(dead.length).padStart(3)} rules  ${String(bytes).padStart(8)} B  (${(100 * bytes / inst.bytes).toFixed(1)}% of instance)`);
  for (const f of dead.sort((x, y) => y.bytes - x.bytes).slice(0, 6)) {
    console.log(`        ${String(f.bytes).padStart(7)}B  ${f.name}:${f.startLine}`);
  }
}

console.log('\n=== STRUCTURALLY WORST RULES ACROSS ALL FOUR DIALECTS ===');
const rows = [];
for (const a of report) {
  for (const f of a.instances[0].fns) {
    // composite structural score: size + blind arms + speculative snapshots + depth
    const score =
      f.bytes / 1000 +
      f.ungatedCallFirst * 25 +
      f.totalArms * 3 +
      f.snapshotCount * 20 +
      f.worstGuardGroup * 10 +
      f.maxDepth * 4;
    rows.push({ dialect: a.dialect, f, score });
  }
}
rows.sort((x, y) => y.score - x.score);
for (const r of rows.slice(0, 25)) {
  const f = r.f;
  console.log(
    `${r.score.toFixed(0).padStart(5)}  ${r.dialect.padEnd(5)} ${f.name}:${f.startLine}  ` +
    `${f.bytes}B arms=${f.totalArms} ungated=${f.ungatedArms}(call=${f.ungatedCallFirst}) ` +
    `snap=${f.snapshotCount}(att=${f.attemptSnapshots}/not=${f.notSnapshots}) worstGuardGroup=${f.worstGuardGroup} depth=${f.maxDepth}`
  );
}
